const allInputs = $input.all();

console.log(`Processing ${allInputs.length} inputs`);

const scoredItems = [];

// Process all inputs
for (const input of allInputs) {
  const item = input.json;
  let score = 0;

  // Skip if no title
  if (!item.title) {
    console.log('Skipping item with no title');
    continue;
  }

  console.log(`Processing: ${item.title}`);

  // Score based on existing score from previous node
  if (item.score) {
    score += item.score;
  }

  // Score based on age_hours if available
  if (item.age_hours !== undefined) {
    if (item.age_hours <= 6) {
      score += 5;
    } else if (item.age_hours <= 24) {
      score += 3;
    } else if (item.age_hours <= 48) {
      score += 1;
    }
  }

  // Score based on source if available
  if (item.source) {
    const premiumSources = ['venturebeat.com', 'techcrunch.com', 'bloomberg.com', 'decrypt.co'];
    if (premiumSources.some(s => item.source.includes(s))) {
      score += 5;
    }
  }

  scoredItems.push({
    title: item.title,
    link: item.link,
    description: item.description || item.pubDate || '',
    pubDate: item.pubDate,
    source: item.source,
    age_hours: item.age_hours,
    score: Math.round(score * 10) / 10,
    score_breakdown: item.score_breakdown
  });
}

console.log(`Scored ${scoredItems.length} items`);

// Sort by score
scoredItems.sort((a, b) => b.score - a.score);

// Show top 5
console.log('\nTop 5 items:');
scoredItems.slice(0, 5).forEach((item, i) => {
  console.log(`${i + 1}. Score: ${item.score} | Age: ${item.age_hours}h | Source: ${item.source}`);
  console.log(`   ${item.title}`);
});

// Get top 15
const topItems = scoredItems
  .slice(0, 15)
  .map(item => ({ json: item }));

console.log(`\nReturning top ${topItems.length} items`);

return topItems;

const items = $input.all();
const scoredItems = [];

console.log(`Scoring ${items.length} RSS feed items`);

for (const item of items) {
  const feedItem = item.json;
  let score = 0;
  let scoreBreakdown = [];

  // Skip if no title or link
  if (!feedItem.title || !feedItem.link) continue;

  // ═══════════════════════════════════════
  // 1. RECENCY SCORE (Max: 10 points)
  // ═══════════════════════════════════════
  const pubDate = new Date(feedItem.pubDate || feedItem.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 6) {
    score += 10;
    scoreBreakdown.push('Very recent (6h): +10');
  } else if (hoursOld <= 24) {
    score += 7;
    scoreBreakdown.push('Recent (24h): +7');
  } else if (hoursOld <= 48) {
    score += 4;
    scoreBreakdown.push('1-2 days: +4');
  } else if (hoursOld <= 168) { // 1 week
    score += 2;
    scoreBreakdown.push('This week: +2');
  } else {
    score += 0.5;
    scoreBreakdown.push('Old: +0.5');
  }

  // ═══════════════════════════════════════
  // 2. DAMU'S EXPERTISE KEYWORDS (Max: 20 points)
  // ═══════════════════════════════════════
  const title = (feedItem.title || '').toLowerCase();
  const description = (feedItem.description || '').toLowerCase();
  const content = title + ' ' + description;

  // High-priority keywords (Damu's core expertise)
  const highPriorityKeywords = {
    // AI
    'artificial intelligence': 5,
    'AI strategy': 5,
    'enterprise AI': 5,
    'AI governance': 4,
    'AI compliance': 4,
    'machine learning': 3,

    // Tokenization & RWA
    'tokenization': 5,
    'RWA': 5,
    'real world assets': 5,
    'asset tokenization': 5,

    // Stablecoins
    'stablecoin': 5,
    'USDC': 4,
    'stablecoin regulation': 5,

    // Institutional
    'family office': 5,
    'sovereign wealth': 5,
    'UHNWI': 5,
    'institutional investor': 4,
    'institutional adoption': 4,

    // Compliance & Regulation
    'regulatory framework': 4,
    'compliance': 3,
    'SEC': 3,
    'regulation': 2
  };

  // Medium-priority keywords
  const mediumPriorityKeywords = {
    'blockchain': 3,
    'digital assets': 3,
    'crypto': 2,
    'DeFi': 2,
    'smart contract': 3,
    'web3': 2,
    'fintech': 2,
    'treasury': 3,
    'infrastructure': 2
  };

  // Check high-priority keywords
  for (const [keyword, points] of Object.entries(highPriorityKeywords)) {
    if (content.includes(keyword.toLowerCase())) {
      score += points;
      scoreBreakdown.push(`"${keyword}": +${points}`);
    }
  }

  // Check medium-priority keywords
  for (const [keyword, points] of Object.entries(mediumPriorityKeywords)) {
    if (content.includes(keyword.toLowerCase())) {
      score += points;
      scoreBreakdown.push(`"${keyword}": +${points}`);
    }
  }

  // ═══════════════════════════════════════
  // 3. SOURCE QUALITY (Max: 10 points)
  // ═══════════════════════════════════════
  const link = feedItem.link.toLowerCase();

  const premiumSources = {
    'bloomberg.com': 10,
    'ft.com': 10,
    'wsj.com': 10,
    'reuters.com': 9,
    'theinformation.com': 9,
    'economist.com': 9,
    'coindesk.com': 8,
    'theblock.co': 8,
    'techcrunch.com': 7,
    'venturebeat.com': 7,
    'a16z.com': 8,
    'stripe.com/blog': 8,
    'circle.com/blog': 8,
    'coinbase.com/blog': 8,
    'sec.gov': 9,
    'mckinsey.com': 9,
    'bcg.com': 9,
    'gartner.com': 8
  };

  for (const [domain, points] of Object.entries(premiumSources)) {
    if (link.includes(domain)) {
      score += points;
      scoreBreakdown.push(`Source (${domain}): +${points}`);
      break;
    }
  }

  // ═══════════════════════════════════════
  // 4. INSTITUTIONAL LANGUAGE (Max: 5 points)
  // ═══════════════════════════════════════
  const institutionalPhrases = [
    'enterprise',
    'institutional',
    'board',
    'governance',
    'fiduciary',
    'investment strategy',
    'portfolio',
    'risk management',
    'due diligence',
    'asset allocation'
  ];

  let institutionalCount = 0;
  for (const phrase of institutionalPhrases) {
    if (content.includes(phrase)) {
      institutionalCount++;
    }
  }

  const institutionalScore = Math.min(institutionalCount * 1, 5);
  if (institutionalScore > 0) {
    score += institutionalScore;
    scoreBreakdown.push(`Institutional language: +${institutionalScore}`);
  }

  // ═══════════════════════════════════════
  // 5. AVOID RETAIL/CONSUMER CONTENT (-10 points)
  // ═══════════════════════════════════════
  const retailKeywords = [
    'how to buy',
    'best wallet',
    'top 10 coins',
    'meme coin',
    'price prediction',
    'to the moon',
    'rug pull',
    'airdrop',
    'giveaway',
    'get rich'
  ];

  for (const keyword of retailKeywords) {
    if (content.includes(keyword)) {
      score -= 10;
      scoreBreakdown.push(`Retail content (${keyword}): -10`);
      break;
    }
  }

  // ═══════════════════════════════════════
  // 6. TITLE QUALITY (Max: 5 points)
  // ═══════════════════════════════════════
  // Prefer analysis over news
  if (title.includes('analysis') || title.includes('report') || title.includes('study')) {
    score += 5;
    scoreBreakdown.push('Analysis/Report: +5');
  } else if (title.includes('announces') || title.includes('launches')) {
    score += 3;
    scoreBreakdown.push('Announcement: +3');
  }

  // Prefer data-driven content
  if (content.match(/\d+%|\$\d+[MBT]|\d+ million|\d+ billion/)) {
    score += 3;
    scoreBreakdown.push('Contains data: +3');
  }

  // Round final score
  score = Math.round(score * 10) / 10;

  scoredItems.push({
    title: feedItem.title,
    link: feedItem.link,
    description: feedItem.description,
    pubDate: feedItem.pubDate,
    source: feedItem.link.split('/')[2], // Extract domain
    age_hours: Math.round(hoursOld),
    score: score,
    score_breakdown: scoreBreakdown.join(' | ')
  });
}

console.log(`Scored ${scoredItems.length} items`);

// Sort by score
scoredItems.sort((a, b) => b.score - a.score);

// Show top 5 scores for debugging
console.log('\n═══════════════════════════════════════');
console.log('TOP 5 SCORED ITEMS:');
console.log('═══════════════════════════════════════');
scoredItems.slice(0, 5).forEach((item, i) => {
  console.log(`\n${i + 1}. ${item.title}`);
  console.log(`   Score: ${item.score} | Age: ${item.age_hours}h | Source: ${item.source}`);
  console.log(`   Breakdown: ${item.score_breakdown}`);
});

// Get top 15
const topItems = scoredItems
  .slice(0, 15)
  .map(item => ({ json: item }));

console.log(`\nReturning top ${topItems.length} items`);

return topItems;

const items = $input.all();

for (const item of items) {
  const html = item.json.html || item.json.data;
  let imageUrl = '';

  if (html) {
    // Try multiple methods to find the best image

    // Method 1: Open Graph image (most reliable for articles)
    let match = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
    if (match) {
      imageUrl = match[1];
    }

    // Method 2: Twitter card image
    if (!imageUrl) {
      match = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 3: Featured/hero images (common in blog posts)
    if (!imageUrl) {
      const featuredSelectors = [
        /<img[^>]*class=["'][^"']*featured[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*hero[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*wp-post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i
      ];

      for (const regex of featuredSelectors) {
        match = html.match(regex);
        if (match) {
          imageUrl = match[1];
          break;
        }
      }
    }

    // Method 4: First image in article content
    if (!imageUrl) {
      match = html.match(/<(?:article|div[^>]*class=["'][^"']*(?:content|post|article)[^"']*["'])[^>]*>.*?<img[^>]*src=["']([^"']+)["'][^>]*>/is);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 5: Any reasonably sized image (width > 300px)
    if (!imageUrl) {
      const imgMatches = html.match(/<img[^>]*src=["']([^"']+)["'][^>]*>/gi);
      if (imgMatches) {
        for (const imgTag of imgMatches) {
          const srcMatch = imgTag.match(/src=["']([^"']+)["']/);
          const widthMatch = imgTag.match(/width=["']?(\d+)/);

          if (srcMatch && (!widthMatch || parseInt(widthMatch[1]) > 300)) {
            imageUrl = srcMatch[1];
            break;
          }
        }
      }
    }

    // Clean up relative URLs
    if (imageUrl && imageUrl.startsWith('//')) {
      imageUrl = 'https:' + imageUrl;
    } else if (imageUrl && imageUrl.startsWith('/')) {
      const linkUrl = item.json.link || '';
      const baseUrl = linkUrl.match(/^https?:\/\/[^\/]+/);
      if (baseUrl) {
        imageUrl = baseUrl[0] + imageUrl;
      }
    }

    // Validate it's actually an image
    if (imageUrl && !imageUrl.match(/\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i)) {
      // Check if it might be a valid image URL without extension
      if (!imageUrl.includes('image') && !imageUrl.includes('photo') && !imageUrl.includes('pic')) {
        imageUrl = '';
      }
    }
  }

  // Add image data to your item
  item.json.imageUrl = imageUrl;
  item.json.hasImage = !!imageUrl;

  // Log for debugging
  if (imageUrl) {
    console.log(`Found image: ${imageUrl}`);
  } else {
    console.log('No image found for article');
  }
}

return items;

