// Get first item from previous node
const input = $input.first().json;

// 🔧 1. Figure out where your article text lives
// Adjust these property names to match your JinAI output
let content =
  input.markdownContent ||  // e.g. "Markdown Content"
  input.markdown ||         // generic markdown field
  input.content ||          // generic content field
  input.text ||             // generic text field
  input.body ||             // generic body field
  input;                    // fallback: raw json

// Always normalize to string
if (typeof content !== 'string') {
  content = JSON.stringify(content);
}

/**
 * Find the best candidate for the article's main image URL.
 * Search order:
 *  1) <meta property="og:image" ...>
 *  2) Markdown images ![alt](url)
 *  3) <img src="...">, skipping logos/icons
 *  4) Any bare image-looking URL
 */
function findMainImage(text) {
  let match;

  // 1) og:image meta tag
  match =
    text.match(
      /<meta[^>]+property=["']og:image["'][^>]+content=["'](https?:\/\/[^"']+)["'][^>]*>/i
    ) ||
    text.match(
      /<meta[^>]+content=["'](https?:\/\/[^"']+)["'][^>]+property=["']og:image["'][^>]*>/i
    );

  if (match && match[1]) {
    return { url: match[1], source: 'og:image meta' };
  }

  // 2) Markdown image syntax: ![alt](https://...)
  match = text.match(/!\[[^\]]*]\((https?:\/\/[^)\s]+)\)/);
  if (match && match[1]) {
    return { url: match[1], source: 'markdown_image' };
  }

  // 3) HTML <img src="..."> (skip obvious icons/logos)
  const imgRegex = /<img[^>]+src=["'](https?:\/\/[^"']+)["'][^>]*>/gi;
  let imgMatch;
  while ((imgMatch = imgRegex.exec(text)) !== null) {
    const url = imgMatch[1];
    // Skip small decorative assets if possible
    if (!/logo|icon|favicon|sprite|emoji|avatar/i.test(url)) {
      return { url, source: 'html_img' };
    }
  }

  // 4) Bare image URLs (png, jpg, jpeg, gif, webp, svg)
  match = text.match(
    /https?:\/\/[^\s)>'"]+\.(?:png|jpe?g|gif|webp|svg)/i
  );
  if (match && match[0]) {
    return { url: match[0], source: 'bare_image_url' };
  }

  // Nothing found
  return { url: null, source: 'none' };
}

const imageResult = findMainImage(content);

// Return the original data plus mainImageUrl
return [
  {
    json: {
      ...input,
      mainImageUrl: imageResult.url,
      mainImageSourceType: imageResult.source,
      imageDebug: {
        contentLength: content.length,
        contentPreview: content.slice(0, 200) + '...',
      },
    },
  },
