// N8N Code Node - Clean and validate image URLs
// Handles proxies, redirects, and extracts real image URLs

const items = $input.all();
const processedItems = [];

for (const item of items) {
  const article = item.json;
  let imageUrl = article.image || article.urlToImage || null;

  if (!imageUrl) {
    // No image found
    processedItems.push({
      ...article,
      cleanImageUrl: null,
      imageStatus: 'no_image'
    });
    continue;
  }

  // Function to extract real URL from proxy/redirect URLs
  function extractRealImageUrl(url) {
    // CASE 1: Yahoo Image Proxy
    // Format: https://s.yimg.com/ny/api/res/1.2/xxx--/YXBwaWQ9.../https://s.yimg.com/os/creatr-uploaded-images/2025-12/xxx
    if (url.includes('yimg.com/ny/api/res')) {
      // Extract everything after the last 'https://' or 'http://'
      const matches = url.match(/https?:\/\/[^\/]+\/[^\s]+$/);
      if (matches) {
        return matches[0];
      }

      // Alternative: Split by '/https://' and take the last part
      const parts = url.split(/\/https?:\/\//);
      if (parts.length > 1) {
        return 'https://' + parts[parts.length - 1];
      }
    }

    // CASE 2: Google Image Proxy
    // Format: https://lh3.googleusercontent.com/proxy/...?url=https://actual-image.jpg
    if (url.includes('googleusercontent.com/proxy')) {
      const urlParam = new URL(url).searchParams.get('url');
      if (urlParam) return decodeURIComponent(urlParam);
    }

    // CASE 3: Reddit Image Proxy
    // Format: https://external-preview.redd.it/...?url=https://actual-image.jpg
    if (url.includes('external-preview.redd.it')) {
      const urlParam = new URL(url).searchParams.get('url');
      if (urlParam) return decodeURIComponent(urlParam);
    }

    // CASE 4: Twitter/X Image CDN (already clean, but ensure proper format)
    if (url.includes('pbs.twimg.com')) {
      // Twitter images are direct, just ensure they have format parameter
      if (!url.includes('format=')) {
        return url + (url.includes('?') ? '&' : '?') + 'format=jpg&name=large';
      }
      return url;
    }

    // CASE 5: Facebook CDN (extract from fbcdn)
    if (url.includes('fbcdn.net')) {
      // Facebook URLs are usually direct but might have tracking params
      return url.split('?')[0]; // Remove query params
    }

    // CASE 6: LinkedIn CDN
    if (url.includes('licdn.com/dms/image')) {
      // LinkedIn images are direct
      return url;
    }

    // CASE 7: Generic URL-encoded image in query parameter
    // Format: https://proxy.com/image?url=https%3A%2F%2Factual-image.jpg
    const urlParams = ['url', 'image', 'src', 'img'];
    try {
      const urlObj = new URL(url);
      for (const param of urlParams) {
        const value = urlObj.searchParams.get(param);
        if (value && (value.startsWith('http://') || value.startsWith('https://'))) {
          return decodeURIComponent(value);
        }
      }
    } catch (e) {
      // Not a valid URL, continue
    }

    // CASE 8: Data URI (base64 encoded images)
    if (url.startsWith('data:image')) {
      return url; // Keep as-is, valid format
    }

    // CASE 9: Relative URLs (need base URL)
    if (url.startsWith('/') || url.startsWith('./')) {
      // Try to construct full URL from article source
      if (article.url) {
        try {
          const baseUrl = new URL(article.url);
          return `${baseUrl.protocol}//${baseUrl.host}${url.startsWith('/') ? url : '/' + url}`;
        } catch (e) {
          return null; // Can't construct valid URL
        }
      }
      return null;
    }

    // No proxy detected, return original
    return url;
  }

  // Function to validate if URL is actually an image
  function isValidImageUrl(url) {
    if (!url) return false;

    // Check for data URI
    if (url.startsWith('data:image')) return true;

    // Check for common image extensions
    const imageExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg', '.bmp', '.ico'];
    const urlLower = url.toLowerCase();

    // Check if URL ends with image extension
    if (imageExtensions.some(ext => urlLower.includes(ext))) return true;

    // Check for known image CDN domains
    const imageCdns = [
      'imgur.com',
      'cloudinary.com',
      'unsplash.com',
      'pexels.com',
      'pixabay.com',
      'flickr.com',
      'twimg.com',
      'fbcdn.net',
      'googleusercontent.com',
      'licdn.com',
      'cloudfront.net',
      'akamaihd.net',
      'wp.com',
      'medium.com',
      'githubusercontent.com'
    ];

    if (imageCdns.some(cdn => urlLower.includes(cdn))) return true;

    // Check for common image-related paths
    const imagePaths = ['/image/', '/img/', '/photo/', '/picture/', '/media/', '/upload/', '/static/'];
    if (imagePaths.some(path => urlLower.includes(path))) return true;

    // If it's a URL without extension, it might still be valid (API endpoints)
    try {
      new URL(url);
      return true; // Valid URL format, assume it's an image
    } catch (e) {
      return false;
    }
  }

  // Function to detect faulty/broken URLs
  function isFaultyUrl(url) {
    if (!url) return true;

    // Check for common issues
    const faultyPatterns = [
      /^https?:\/\/https?:\/\//, // Double protocol
      /\s/, // Contains whitespace
      /\.\.$/, // Ends with ..
      /\/\/$/, // Ends with //
      /<|>|{|}|\[|\]/, // Contains HTML/brackets
      /placeholder/i, // Placeholder image
      /default/i, // Default image
      /no-image/i, // No image indicator
      /^\/\/$/ // Protocol-relative URL without domain
    ];

    return faultyPatterns.some(pattern => pattern.test(url));
  }

  // Process the image URL
  let cleanUrl = extractRealImageUrl(imageUrl);
  let status = 'valid';

  // Validate the extracted URL
  if (!cleanUrl || isFaultyUrl(cleanUrl)) {
    status = 'faulty';
    cleanUrl = null;
  } else if (!isValidImageUrl(cleanUrl)) {
    status = 'invalid_image';
    cleanUrl = null;
  }

  // Try fallback images if main image is faulty
  if (!cleanUrl) {
    // Check for alternative image fields
    const alternatives = [
      article.image,
      article.urlToImage,
      article.thumbnail,
      article.media?.thumbnail,
      article.og_image,
      article.twitter_image
    ].filter(Boolean);

    for (const alt of alternatives) {
      if (alt !== imageUrl) { // Don't recheck the same URL
        const extracted = extractRealImageUrl(alt);
        if (extracted && !isFaultyUrl(extracted) && isValidImageUrl(extracted)) {
          cleanUrl = extracted;
          status = 'valid_fallback';
          break;
        }
      }
    }
  }

  processedItems.push({
    ...article,
    originalImageUrl: imageUrl,
    cleanImageUrl: cleanUrl,
    imageStatus: status,
    hasValidImage: !!cleanUrl
  });
}

