// n8n Function / Code node (JavaScript)
// Input: item.json.markdown (or item.json.text)
// Output: item.json.plainText (LinkedIn-safe)

function decodeEntities(str) {
  return String(str)
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'")
    .replace(/&#x2F;/g, "/");
}

function mdToText(mdRaw) {
  let md = String(mdRaw ?? "");
  md = md.replace(/\r\n?/g, "\n");

  // Remove fenced code fences but keep code text
  md = md.replace(/```[\s\S]*?```/g, (block) =>
    block.replace(/^```.*\n?/, "").replace(/```$/, "").trim()
  );

  // Inline code
  md = md.replace(/`([^`]+)`/g, "$1");

  // Images -> alt text
  md = md.replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1");

  // Links -> link text only
  md = md.replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1");

  // Headings
  md = md.replace(/^#{1,6}\s+/gm, "");

  // Blockquotes
  md = md.replace(/^>\s?/gm, "");

  // Task lists
  md = md.replace(/^\s*[-*+]\s+\[[ xX]\]\s+/gm, "- ");

  // Bullets (convert leading * into "- " BEFORE we strip asterisks)
  md = md.replace(/^\s*[-*+]\s+/gm, "- ");

  // Bold / italic / strike
  md = md.replace(/(\*\*|__)(.*?)\1/g, "$2");
  md = md.replace(/(\*|_)(.*?)\1/g, "$2");
  md = md.replace(/~~(.*?)~~/g, "$1");

  // Strip HTML tags
  md = md.replace(/<\/?[^>]+>/g, "");

  // Decode entities
  md = decodeEntities(md);

  // Cleanup whitespace
  md = md.replace(/[ \t]+\n/g, "\n");
  md = md.replace(/\n{3,}/g, "\n\n");

  return md.trim();
}

function stripAllAsterisks(text) {
  // This guarantees you never see ** or **** in the final output
  return String(text).replace(/\*+/g, "");
}

return items.map((item) => {
  const input = item.json.markdown ?? item.json.text ?? "";
  const plain = mdToText(input);
  item.json.plainText = stripAllAsterisks(plain);
  return item;
});

