    // Keep higher institutional relevance
    if (article.institutional_relevance > existing.institutional_relevance) {
      articlesMap.set(article.article_id, article);
    }
  }
}

const uniqueArticles = Array.from(articlesMap.values());

// Calculate composite score with institutional weight
const scoredArticles = uniqueArticles.map(article => {
  // Freshness score
  let freshnessScore = 5.0;
  const dateStr = (article.published_date || '').toLowerCase();
  if (dateStr.includes('hour') || dateStr.includes('today')) {
    freshnessScore = 10.0;
  } else if (dateStr.includes('yesterday')) {
    freshnessScore = 8.0;
  } else if (dateStr.includes('day') || dateStr.includes('2026-01')) {
    freshnessScore = 6.0;
  }

  // Content quality score
  const factCount = article.key_facts?.length || 0;
  const hasNumbers = article.key_facts?.some(fact => /\d/.test(fact)) || false;
  const hasExecutives = article.executives?.length > 0 || false;
  const qualityScore = factCount * 1.5 + (hasNumbers ? 3 : 0) + (hasExecutives ? 2 : 0);

  // Institutional alignment score
  const instScore = article.institutional_relevance || 7.0;
  const hasInstAngle = article.institutional_angle && article.institutional_angle.length > 50;
  const institutionalScore = instScore + (hasInstAngle ? 2 : 0);

  // Priority boost
  const priorityBoost = article.query_priority === 'high' ? 3 : 1;

  // Audience alignment
  const audienceBoost = ['UHNWI', 'family_office', 'sovereign_wealth'].includes(article.target_audience) ? 2 : 0;

  // Composite score - heavily weighted toward institutional relevance
  const compositeScore = 
    institutionalScore * 0.4 +  // 40% institutional relevance (most important)
    freshnessScore * 0.2 +      // 20% freshness
    qualityScore * 0.2 +        // 20% content quality
    priorityBoost * 0.1 +       // 10% query priority
    audienceBoost * 0.1;        // 10% audience fit

  return {
    ...article,
    composite_score: Math.round(compositeScore * 10) / 10,
    freshness_score: freshnessScore,
    quality_score: qualityScore,
    institutional_score: institutionalScore
  };
});

