  { keyword: "treasury", boost: 1.5 },
  { keyword: "DeFi", boost: 1.3 },
  { keyword: "web3", boost: 1.3 }
];

// Score topics based on Damu's expertise
const scoredTopics = topics.map(topic => {
  let expertiseScore = 0;
  let matchedKeywords = [];

  // Check if topic matches Damu's expertise
  for (const expertise of damuExpertise) {
    const topicLower = topic.topic.toLowerCase();
    const keywordsLower = (topic.keywords || []).join(' ').toLowerCase();
    const angleLower = (topic.institutional_angle || '').toLowerCase();

    if (topicLower.includes(expertise.keyword.toLowerCase()) || 
        keywordsLower.includes(expertise.keyword.toLowerCase()) ||
