// Multiple items - select best based on Damu expertise
console.log(`Multiple items detected - selecting best match for Damu's expertise`);

// Function to calculate Damu expertise score
function calculateDamuScore(article) {
  let score = 0;

  // Extract text fields for analysis
  const headline = (article.headline || article.title || article.article_title || '').toLowerCase();
  const summary = (article.why_selected || article.summary || article.description || '').toLowerCase();
  const source = (article.source || '').toLowerCase();
  const content = headline + ' ' + summary + ' ' + source;

  // Damu's core expertise areas with weights
  const expertiseKeywords = {
    // Web3 & Blockchain (highest priority)
    web3: { 
      keywords: ['web3', 'blockchain', 'stablecoin', 'tokenization', 'defi', 'crypto', 'digital asset', 'smart contract'], 
      weight: 12 
    },

    // Financial Infrastructure
    fintech: { 
      keywords: ['payment', 'financial infrastructure', 'enterprise blockchain', 'fintech', 'banking', 'settlement'], 
      weight: 10 
    },

    // Cloud & Innovation (AWS background)
    cloud: { 
      keywords: ['aws', 'amazon web services', 'cloud', 'infrastructure', 'platform', 'saas'], 
      weight: 9 
    },

    // Institutional Finance
    institutional: { 
      keywords: ['institutional', 'family office', 'sovereign wealth', 'asset management', 'hedge fund', 'private equity'], 
      weight: 10 
    },

    // Strategic & Governance
    strategic: { 
      keywords: ['strategic', 'governance', 'compliance', 'regulation', 'framework', 'risk management'], 
      weight: 8 
    },

    // Innovation & Transformation
    innovation: { 
      keywords: ['innovation', 'transformation', 'digital transformation', 'disruption', 'emerging'], 
      weight: 7 
    }
  };

  // Calculate keyword-based score
  for (const [category, data] of Object.entries(expertiseKeywords)) {
    let categoryMatches = 0;
    for (const keyword of data.keywords) {
      if (content.includes(keyword)) {
        categoryMatches++;
      }
    }
    // Award points based on matches (diminishing returns)
    if (categoryMatches > 0) {
      score += data.weight * Math.min(categoryMatches, 3);
    }
  }

  // Premium source bonus
  const premiumSources = [
    'bloomberg', 'financial times', 'ft.com', 'wsj', 'wall street journal',
    'reuters', 'the information', 'mckinsey', 'bcg', 'gartner',
    'coindesk', 'the block', 'circle', 'a16z', 'sequoia'
  ];

  for (const premiumSource of premiumSources) {
    if (source.includes(premiumSource)) {
      score += 20;
      break;
    }
  }

  // Use existing scores if available
  const existingScore = article.selection_score || article.institutional_relevance || 0;
  if (existingScore > 0) {
    score += existingScore * 5; // Weight existing scores
  }

  // Recency bonus
  const publishedDate = article.published_date || article.article_published_date || '';
  if (publishedDate) {
    try {
      const pubDate = new Date(publishedDate);
      const daysSince = (Date.now() - pubDate.getTime()) / (1000 * 60 * 60 * 24);

      if (daysSince <= 7) score += 15;      // Last week
      else if (daysSince <= 30) score += 8; // Last month
      else if (daysSince <= 90) score += 3; // Last quarter
    } catch (e) {
      // Invalid date, skip bonus
    }
  }

  // Strategic content indicators
  if (headline.includes('institutional') || headline.includes('enterprise')) {
    score += 10; // Headlines matter more
  }

  return score;
}

// Score all articles
const scoredArticles = items.map((item, index) => {
  const article = item.json;
  const damuScore = calculateDamuScore(article);

  console.log(`Article ${index + 1}: "${article.headline || article.title}" - Score: ${damuScore.toFixed(1)}`);

  return {
